'use client'

import { useState, useEffect } from 'react'
import { TimeSession } from '@/types/task'

export function useTimeTracker() {
  const [sessions, setSessions] = useState<TimeSession[]>([])
  const [activeSession, setActiveSession] = useState<TimeSession | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    // Load sessions from localStorage
    const storedSessions = localStorage.getItem('timeSessions')
    if (storedSessions) {
      const parsedSessions = JSON.parse(storedSessions)
      // Convert date strings back to Date objects
      const sessionsWithDates = parsedSessions.map((session: any) => ({
        ...session,
        startTime: new Date(session.startTime),
        endTime: session.endTime ? new Date(session.endTime) : null,
      }))
      setSessions(sessionsWithDates)

      // Check if there's an active session
      const active = sessionsWithDates.find((s: TimeSession) => !s.endTime)
      if (active) {
        setActiveSession(active)
      }
    }
    setIsLoading(false)
  }, [])

  useEffect(() => {
    // Save sessions to localStorage whenever they change
    if (!isLoading) {
      localStorage.setItem('timeSessions', JSON.stringify(sessions))
    }
  }, [sessions, isLoading])

  const startSession = (activity: string, description?: string) => {
    // Stop any active session first
    if (activeSession) {
      stopSession()
    }

    const now = new Date()
    const newSession: TimeSession = {
      id: crypto.randomUUID(),
      activity,
      description,
      startTime: now,
      endTime: undefined,
      date: now.toISOString().split('T')[0], // YYYY-MM-DD
    }

    setSessions((prev) => [...prev, newSession])
    setActiveSession(newSession)
    return newSession
  }

  const addManualSession = (
    activity: string,
    startTime: Date,
    endTime: Date,
    description?: string
  ) => {
    const newSession: TimeSession = {
      id: crypto.randomUUID(),
      activity,
      description,
      startTime,
      endTime,
      date: startTime.toISOString().split('T')[0],
    }

    setSessions((prev) => [...prev, newSession])
    return newSession
  }

  const stopSession = () => {
    if (!activeSession) return

    const now = new Date()
    setSessions((prev) =>
      prev.map((session) =>
        session.id === activeSession.id
          ? { ...session, endTime: now }
          : session
      )
    )
    setActiveSession(null)
  }

  const updateSession = (id: string, updates: Partial<TimeSession>) => {
    setSessions((prev) =>
      prev.map((session) =>
        session.id === id ? { ...session, ...updates } : session
      )
    )

    if (activeSession?.id === id) {
      setActiveSession((prev) => (prev ? { ...prev, ...updates } : null))
    }
  }

  const deleteSession = (id: string) => {
    setSessions((prev) => prev.filter((session) => session.id !== id))
    if (activeSession?.id === id) {
      setActiveSession(null)
    }
  }

  const getSessionsByDate = (date: string) => {
    return sessions
      .filter((session) => session.date === date)
      .sort((a, b) => a.startTime.getTime() - b.startTime.getTime())
  }

  const getTodaySessions = () => {
    const today = new Date().toISOString().split('T')[0]
    return getSessionsByDate(today)
  }

  const getTotalTimeForDate = (date: string) => {
    const daySessions = getSessionsByDate(date)
    return daySessions.reduce((total, session) => {
      if (!session.endTime) {
        // If session is active, calculate time until now
        return total + (new Date().getTime() - session.startTime.getTime())
      }
      return total + (session.endTime.getTime() - session.startTime.getTime())
    }, 0)
  }

  return {
    sessions,
    activeSession,
    isLoading,
    startSession,
    stopSession,
    addManualSession,
    updateSession,
    deleteSession,
    getSessionsByDate,
    getTodaySessions,
    getTotalTimeForDate,
  }
}

